changeSet.sql:
create or replace function get_price_after_sale(original_price numeric, ds discount) returns numeric
    language plpgsql
    as
    $$
                DECLARE
                discount_amount NUMERIC;
        final_price NUMERIC;
                begin
        if (ds.type = 0) then
            discount_amount := original_price * (ds.value) / 100;
        elseif ds.type = 1 then
            discount_amount := ds.value;
                else
            discount_amount := 0;
                end if;

        final_price := original_price - discount_amount;

                return final_price;
                end
    $$;
